def normalize_row(row, expected=None):
    name = row.get("protocol")
    if expected and name != expected:
        row["protocol"] = expected
        name = expected
    if name not in PROTOCOLS:
        raise ValueError(f"unexpected protocol {name!r}")
    for dim in DIMS:
        val = row.get(dim)
        if val == "NA" or val is None:
            row[dim] = None
            continue
        val = float(val)
        if val not in SCORES:
            val = min(SCORES, key=lambda s: abs(s - val))
        row[dim] = val
    for prop in PROPS:
        lab = str(row.get(prop) or "no").lower()
        if lab not in PROP_LABELS:
            lab = "no"
        row[prop] = lab
    count = sum(1 for p in PROPS if row[p] in {"yes", "partial"})
    row["A_count"] = count
    row["A"] = 0.0 if count <= 1 else (1.0 if count <= 4 else 2.0)
    return row
